import{_ as p,a0 as i,w as r,s,ao as l,I as a,a1 as o,A as e,x as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const U=JSON.parse('{"title":"安裝Ubuntu13.10後必做的10件事 | LCTT x X-CMD","titleTemplate":false,"description":"安裝Ubuntu13.10後必做的10件事 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安裝Ubuntu13.10後必做的10件事 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安裝Ubuntu13.10後必做的10件事 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/10 Things To Do After Installing Ubuntu 13.10","title":"安裝Ubuntu13.10後必做的10件事","tag":"201311","desc":""},"relativePath":"201311/10 Things To Do After Installing Ubuntu 13.10.md","filePath":"[post].md"}'),b={name:"201311/10 Things To Do After Installing Ubuntu 13.10.md"};function m(d,t,g,h,_,T){const u=i("Link");return r(),s("div",null,[t[14]||(t[14]=l('<h1 id="安裝ubuntu13-10後必做的10件事" tabindex="-1">安裝Ubuntu13.10後必做的10件事 <a class="header-anchor" href="#安裝ubuntu13-10後必做的10件事" aria-label="Permalink to “安裝Ubuntu13.10後必做的10件事”">​</a></h1><p><strong>Ubuntu 13.10發佈了，而且你已經升級了，然後你想知道現在要做些什麼。不要着急，這裏有10件安裝完Ubuntu 13.10後必做的事。</strong></p><p>我們以前為ubuntu每個版本整理了一個安裝後核對表，但是因為新功能的到來以及不斷的進步，我們建議的步驟也在不斷改變和轉換。</p><p>因此，升級到ubuntu 13.10後最好做哪些事情呢？</p><h3 id="_1-加快速度" tabindex="-1">1. 加快速度 <a class="header-anchor" href="#_1-加快速度" aria-label="Permalink to “1. 加快速度”">​</a></h3><p>儘管Ubuntu 13.10相較於之前的發佈版包含了較少的面向用户的特徵，但是新的Smart scopes服務還是不可錯過的。</p><h3 id="_2-使用第三方驅動" tabindex="-1">2. 使用第三方驅動 <a class="header-anchor" href="#_2-使用第三方驅動" aria-label="Permalink to “2. 使用第三方驅動”">​</a></h3><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2013/04/drivers.jpg" alt=""></p><p>Ubuntu本身已經支持了大量的硬件。但是雖然免費而又開源的的驅動能力越來越強,在Steam 或 Steam HD video 上玩兒遊戲仍會感覺性能差強人意。</p><p>如果是這樣，可以 <strong>安裝並使用專有驅動</strong> ，它們在Software &amp; Updates （軟件和更新）工具中。</p><p>在啓動器裏打開<em>軟件源應用</em> （或者通過系統設置）然後點擊進入“其他驅動”選項卡，然後按照屏幕上的提示操作。</p><h3 id="_3-安裝ubuntu的影音解碼器" tabindex="-1">3. 安裝Ubuntu的影音解碼器 <a class="header-anchor" href="#_3-安裝ubuntu的影音解碼器" aria-label="Permalink to “3. 安裝Ubuntu的影音解碼器”">​</a></h3><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2013/10/mus.jpg" alt=""></p><p>由於一個很大的法律問題的糾纏，Ubuntu不能即刻支持很多流行的音頻視頻格式。這是一項很大的先天缺陷。</p><p>但是安裝這些支持所需要的僅僅只是幾下點擊。在安裝過程中只需勾選<em>使用限制格式</em> 框來導入需要的解碼器，或者，如果你忘了的話，也可以從Ubuntu軟件中心安裝所有的多媒體相關工具。</p>',15)),a("ul",null,[a("li",null,[o(u,{href:"https://apps.ubuntu.com/cat/applications/ubuntu-restricted-extras/"},{default:e(()=>[...t[0]||(t[0]=[n("安裝第三方解碼器",-1)])]),_:1})])]),t[15]||(t[15]=l('<h3 id="_4-建立你的社會生活" tabindex="-1">4.建立你的社會生活### <a class="header-anchor" href="#_4-建立你的社會生活" aria-label="Permalink to “4.建立你的社會生活###”">​</a></h3><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2013/04/account-toggles.jpg" alt=""></p><p>Facebook, Twitter, Google Talk, Gmail以及其他的社交賬號可以在<em>在線賬號</em> 裏一起設置。</p><p>只需要添加一個網絡然後<strong>決定哪些程序可以使用它</strong>。例如，關掉Empathy，默認啓動Google Chat，從Social Lens裏過濾FaceBook。</p><p>支持的服務包括Twitter, Google, Yahoo!, Facebook (包括 Facebook Chat), Flickr 以及正在增長的大量其他的應用。</p><h3 id="_5-添加第三方應用" tabindex="-1">5. 添加第三方應用 <a class="header-anchor" href="#_5-添加第三方應用" aria-label="Permalink to “5. 添加第三方應用”">​</a></h3><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2013/04/apps.jpg" alt=""></p><p>Ubuntu默認提供了一整套的應用，但是眾口難調，如果你不喜歡某個應用，或者發現自己缺少了什麼應用，你可以很輕鬆的找到並添加軟件。</p><p>打開Ubuntu軟件中心，可以看到成千上萬的程序，包括下面這些很流行的選擇：</p><ul><li><strong>Dropbox</strong> - 流行，跨平台的雲存儲服務</li><li><strong>Steam</strong> – 遊戲發佈平台</li><li><strong>GIMP</strong> – 強大的圖像處理軟件</li><li><strong>VLC</strong> – 流行的影音軟件</li></ul><p>您還可以找到像我們這樣列出了豐富的附加軟件的網站 - 看看我們的<em>Apps</em>標籤你會有一些想法。</p>',11)),a("ul",null,[a("li",null,[o(u,{href:"http://www.omgubuntu.co.uk/category/app"},{default:e(()=>[...t[1]||(t[1]=[n("在OMG上查看Ubuntu App 列表! !",-1)])]),_:1})])]),t[16]||(t[16]=l('<h3 id="_6-保護你的隱私" tabindex="-1">6.保護你的隱私 <a class="header-anchor" href="#_6-保護你的隱私" aria-label="Permalink to “6.保護你的隱私”">​</a></h3><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2013/10/priv.jpg" alt=""></p><p>最近隱私問題是一個燙手山芋，因此很高興看到最新版的Ubuntu改進了它的隱私設置，提供了一個新的界面和大量的新選擇。</p><p>不論你是想在啓動器上隱藏一個文件還是一個應用，限制從睡眠狀態到進入電腦時的訪問，或者選擇什麼樣的系統崩潰向Canonical發送信息，在“隱私和安全”面板總是可以提供你想要的工具。</p><h3 id="_7-享受互聯網" tabindex="-1">7.享受互聯網 <a class="header-anchor" href="#_7-享受互聯網" aria-label="Permalink to “7.享受互聯網”">​</a></h3><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2013/04/gmails.jpg" alt=""></p><p>Canonical宣稱在Ubuntu Touch 上，網站可以很容易的打包、整合並用於安裝， 以吸引web開發人員。</p><p>該方式已經包含在桌面 Ubuntu 一些版本中。超過300個流行網站-包括Gmail, Yahoo! 和Rd.io-可以和桌面無縫集成。</p><p>例如，添加 GMail， 您可以在啓動器和消息菜單上獲得喜愛的Gmail選項； 啓用Rd.io，您可以使用“聲音”（Sound) 菜單控制回放。</p><h3 id="_8-設置自己的unity-yours" tabindex="-1">8. 設置自己的Unity Yours <a class="header-anchor" href="#_8-設置自己的unity-yours" aria-label="Permalink to “8. 設置自己的Unity Yours”">​</a></h3><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2013/10/unity_tweak_tool_310.png" alt=""></p><p>Unity比人們想的定製性更好。 <em>Unity Tweak Tool</em> 是一個第三方應用，可以讓您調整桌面Unity以打造一個適合您的環境。</p><p>選擇包括:</p><ul><li>調整啓動器透明度</li><li>設置啓動器圖標動畫</li><li>啓動工作台</li><li>設置快捷鍵</li><li>移動窗口的控制</li></ul><p>但是,不要期望太大，它不會讓你移動啓動器的。</p>',15)),a("ul",null,[a("li",null,[o(u,{href:"apt:unity-tweak-tool"},{default:e(()=>[...t[2]||(t[2]=[n("從Ubuntu軟件中心安裝Unity Tweak Tool",-1)])]),_:1})])]),t[17]||(t[17]=l('<h3 id="_9-過濾噪音" tabindex="-1">9. 過濾噪音 <a class="header-anchor" href="#_9-過濾噪音" aria-label="Permalink to “9. 過濾噪音”">​</a></h3><p>Ubuntu’s新的‘Smart Scopes’服務號稱要做成一個很方便的工具，但是現在還不像聲稱的那樣智能。</p><p>好消息是這個特性只需一擊就可以關閉，所以沒有必要因噎廢食順帶着排斥Ubuntu。</p><p>如果你每次搜索時還順帶了一堆毫不相關的不知名的音樂結果或者購物建議，你可以單獨禁用該範圍。</p><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2013/10/Screen-Shot-2013-10-15-at-11.36.26-750x480.png" alt=""></p><p>如果你發現自己每一個搜索都被無關的音樂結果淹沒了，可以禁用“音樂範圍”。不想要亞馬遜的建議？關掉它。</p><h3 id="_10-傳播關於ubuntu13-10的信息" tabindex="-1">10. 傳播關於Ubuntu13.10的信息 <a class="header-anchor" href="#_10-傳播關於ubuntu13-10的信息" aria-label="Permalink to “10. 傳播關於Ubuntu13.10的信息”">​</a></h3><p>我知道，在我們的“應當去做”列表上這是比較尷尬的一項。但是隻有人們知道Ubuntu 13.10才會去嘗試它，因此請出一份力量，多多分享關於它的新聞。</p><p>無論你是把這篇文章貼到Facebook上，還是為你的OS X粉搭檔製作了一個LiveUSB，對於Ubuntu的認知度的提高都是很有幫助的。</p><p>別忘了享受使用它。去檢查下Facebook上的簡介，聽一些音樂，享受一下用Firefox上網。</p><hr>',11)),a("p",null,[t[4]||(t[4]=n("via: ",-1)),o(u,{href:"http://www.omgubuntu.co.uk/2013/10/10-things-installing-ubuntu-13-10"},{default:e(()=>[...t[3]||(t[3]=[n("http://www.omgubuntu.co.uk/2013/10/10-things-installing-ubuntu-13-10",-1)])]),_:1})]),a("p",null,[t[7]||(t[7]=n("譯者：",-1)),o(u,{href:"https://github.com/%E8%AD%AF%E8%80%85ID"},{default:e(()=>[...t[5]||(t[5]=[n("crowner",-1)])]),_:1}),t[8]||(t[8]=n(" 校對：",-1)),o(u,{href:"https://github.com/jasminepeng"},{default:e(()=>[...t[6]||(t[6]=[n("jasminepeng",-1)])]),_:1})]),a("p",null,[t[11]||(t[11]=n("本文由 ",-1)),o(u,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[9]||(t[9]=[n("LCTT",-1)])]),_:1}),t[12]||(t[12]=n(" 原創翻譯，",-1)),o(u,{href:"http://linux.cn/"},{default:e(()=>[...t[10]||(t[10]=[n("Linux中國",-1)])]),_:1}),t[13]||(t[13]=n(" 榮譽推出",-1))])])}const k=p(b,[["render",m]]);export{U as __pageData,k as default};
